        dr = fours[1][0] - fours[0][0]
        dc = fours[1][1] - fours[0][1]
        # The copy is displaced perpendicular to the line through the markers.
        # Select the direction that places its center nearest the other side
        # of the grid from the original.
        candidates = [(-dc, dr), (dc, -dr)]

        def side_score(s):
            return sum((r + s[0]) * r + (c + s[1]) * c for r, c in points)

        shift = max(candidates, key=side_score)
        points |= {(r + shift[0], c + shift[1]) for r, c in points}

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    return [[8 if (r, c) in points else 0 for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]
